-- fixture: a picture floated at the right with a paragraph beside it that fills the column, then the next picture and its text: the
-- text is as tall as each picture, nothing falls behind, and both float as before
return {
    page = 'Fixture', title = 'Fixture', source = '',
    images = {'Bar-map1.jpg', 'Bar-map2.jpg'}, meta = {},
    body = [==[
=2 Tablets in Bar
!Bar-map1.jpg||Bar map 1
* Go in at the south door and walk up the long ramp to the first landing, then turn east and follow the wall past the two braziers until the corridor opens out into the great hall.
* Cross the hall to the far side, keeping the pillars on your left, and take the stairs down; the first tablet is behind the statue at the bottom, in the corner.
* Return to the hall and go north through the arch, past the sleeping guards, and wait for the door to the library to open.
* Search the shelves along the west wall for the second tablet, and do not wake the scribe at the desk.
!Bar-map2.jpg||Bar map 2
* Leave by the way you came, back through the hall and down the ramp to the south door, then wait outside for the next day.
* Go in again at the south door and walk up the long ramp to the first landing, then turn west and follow the wall past the two fountains.
* Cross the courtyard to the far side, keeping the hedges on your right, and take the path down to the gate; the third tablet is behind the bench.
* Return to the courtyard and go north through the arch, past the sleeping guards, and wait for the gate to the garden to open.
]==],
}
